<script setup lang="ts">
import type { Media } from '../library'
import { formatMediaBytes, originalMessageLink } from '../library'
import AppIcon from './AppIcon.vue'
import LibraryPostPreview from './LibraryPostPreview.vue'
const props = defineProps<{ items: Media[]; layout: 'list' | 'cards'; emptyText: string; postKey: string; accountId: string | null; authorized: boolean; available: boolean; version: number; downloadPreviewId?: string; origins?: Record<string, number>; selectable?: boolean; selectedKeys?: string[]; selectionDisabled?: boolean }>()
const emit = defineEmits<{ toggleMedia: [key: string] }>()
const labels: Record<string, string> = { PHOTO: '图片', VIDEO: '视频', AUDIO: '音频', DOCUMENT: '文档', OTHER: '其他' }
function icon(media: Media) { return ({ PHOTO: 'photo', VIDEO: 'video', AUDIO: 'audio' } as Record<string, string>)[media.type] ?? 'file' }
function canPreview(media: Media) { return ['PHOTO', 'VIDEO'].includes(media.type) && (props.downloadPreviewId !== undefined || media.source === 'COMMENT') }
function sourcePage(media: Media) { return media.source === 'MAIN' ? 0 : props.origins?.[media.key] }
</script>
<template>
  <p v-if="!items.length" class="collection-empty">{{ emptyText }}</p>
  <div v-else :class="['media-collection', layout]" role="list" :aria-label="layout === 'cards' ? '媒体卡片' : '媒体列表'">
    <article v-for="media in items" :key="(downloadPreviewId ?? postKey) + ':' + media.key" class="media-collection-item" role="listitem">
      <label v-if="selectable" class="collection-select"><input type="checkbox" :checked="selectedKeys?.includes(media.key)" :disabled="selectionDisabled" :aria-label="`选择媒体 ${media.fileName}`" @change="emit('toggleMedia', media.key)" /><span>选择</span></label>
      <div :class="['collection-image', icon(media)]"><LibraryPostPreview v-if="canPreview(media)" :post-key="postKey" :media-key="media.key" :account-id="accountId" :version="downloadPreviewId ? sourcePage(media) ?? 0 : version" :download-preview-id="downloadPreviewId" :download-page="sourcePage(media)" :authorized="authorized" :available="available" :icon="icon(media)" lazy :compact="layout === 'list'" /><AppIcon v-else :name="icon(media)" /><span v-if="media.type === 'VIDEO'" class="collection-video-mark" aria-hidden="true" /></div>
      <div class="collection-description"><strong>{{ media.fileName || '未提供文件名' }}</strong><p v-if="media.caption">{{ media.caption }}</p><small>{{ media.source === 'MAIN' ? '主帖媒体' : '评论媒体' }}</small></div>
      <div class="collection-meta"><span>{{ labels[media.type] ?? media.type }}</span><small>{{ formatMediaBytes(media.size) }}</small></div>
      <a v-if="originalMessageLink(media.message.link)" :href="originalMessageLink(media.message.link)" target="_blank" rel="noopener noreferrer" class="collection-link">原消息 ↗</a><span v-else class="collection-link unavailable">无可用链接</span>
    </article>
  </div>
</template>
