escription{grid-column:1/-1;padding:10px 11px 7px;min-height:63px}.cards .collection-description p{-webkit-line-clamp:1}.cards .collection-meta{padding:0 11px 11px;display:flex;gap:7px;flex-wrap:wrap}.cards .collection-link{align-self:start;padding:3px 11px 0 0}.collection-empty{padding:24px 13px;text-align:center;font-size:10px;line-height:1.9;color:#93a9b8;background:#f7fafc;border-radius:5px}.media-collection a:focus-visible{outline:2px solid #2986cc;outline-offset:2px}@media(max-width:600px){.list .media-collection-item{grid-template-columns:80px minmax(0,1fr);gap:8px 10px}.list .collection-image{grid-row:span 3}.list .collection-meta{display:flex;gap:7px}.list .collection-link{justify-self:start}.media-collection.cards{grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px}.cards .collection-image{height:110px}}
